python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-edit-add-node/OrderIntake.bpmn')
root = tree.getroot()

ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
}

# Collect all declared ids
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

errors = []

# Every sourceRef/targetRef/bpmnElement must resolve
for el in root.iter():
    for attr in ('sourceRef', 'targetRef', 'attachedToRef', 'bpmnElement'):
        val = el.get(attr)
        if val and val not in all_ids:
            errors.append(f'Unresolved {attr}={val!r} on <{el.tag}>')

# Every BPMNShape/BPMNEdge must have a bpmnElement
proc = root.find('.//bpmn:process', ns)
flow_node_ids = {el.get('id') for el in proc if el.get('id')}
seq_flow_ids = {el.get('id') for el in proc.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow') if el.get('id')}

diag = root.find('.//bpmndi:BPMNDiagram', ns)
plane = diag.find('bpmndi:BPMNPlane', ns) if diag is not None else None
shape_elems = set()
edge_elems = set()
if plane is not None:
    for child in plane:
        tag = child.tag.split('}')[-1]
        be = child.get('bpmnElement')
        if tag == 'BPMNShape': shape_elems.add(be)
        elif tag == 'BPMNEdge': edge_elems.add(be)

# Check every flow node has a shape
for el in proc:
    tag = el.tag.split('}')[-1]
    if tag in ('startEvent','endEvent','scriptTask','userTask','serviceTask','task','exclusiveGateway','parallelGateway','inclusiveGateway','subProcess','callActivity','boundaryEvent','intermediateCatchEvent','intermediateThrowEvent'):
        eid = el.get('id')
        if eid and eid not in shape_elems:
            errors.append(f'Flow node {eid!r} has no BPMNShape')

# Check every sequenceFlow has an edge
for sf in proc.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'):
    eid = sf.get('id')
    if eid and eid not in edge_elems:
        errors.append(f'SequenceFlow {eid!r} has no BPMNEdge')

if errors:
    for e in errors: print('ERROR:', e)
    exit(1)
else:
    print('VALID')
"
